"""sitemap.xml (2026-10-28): generated by this script, no longer hand-edited.

Library pages (content/*.json, minus noindex ones) are listed automatically, dated by their "updated" field
(else "published"), so a new article only needs its JSON. Every other indexable page is listed in PAGES; its
lastmod comes from sitemap-state.json, which keeps a fingerprint of the page's <main> content: when a build
changes that content, lastmod moves to the build date, otherwise it stays put.
Run last, from the repo root: python tools/v4-build/build_sitemap.py (build_all.py does this).
One-off: --seed records fingerprints from the committed HTML (git HEAD) and dates from the existing sitemap."""
import os, sys, re, json, glob, hashlib, datetime, subprocess

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import chrome as C

STATE = os.path.join(HERE, 'sitemap-state.json')
OUT = os.path.join(C.ROOT, 'sitemap.xml')
# Indexable pages that are not content/*.json library pages: (path, changefreq, priority). Add new pages here.
PAGES = [
    ('/', 'weekly', '1.0'),
    ('/ai-native-engineering', 'monthly', '0.9'), ('/ai-engineering-governance', 'weekly', '0.9'), ('/platform', 'monthly', '0.9'),
    ('/fractional-ai-officer', 'monthly', '0.8'), ('/forward-deployed-engineer', 'monthly', '0.8'),
    ('/who-we-help/tech-software', 'monthly', '0.8'), ('/who-we-help/ecommerce-retail', 'monthly', '0.8'),
    ('/who-we-help/operations-heavy', 'monthly', '0.8'), ('/who-we-help/professional-services', 'monthly', '0.8'),
    ('/results', 'monthly', '0.8'), ('/about', 'monthly', '0.8'), ('/insights', 'weekly', '0.8'),
    ('/security', 'monthly', '0.6'), ('/contact', 'monthly', '0.7'), ('/assessment', 'monthly', '0.7'), ('/ai-operations', 'weekly', '0.7'),
    # library pages built in Python rather than from content/*.json
    ('/learn/what-is-ai-native-engineering', 'monthly', '0.8'),
    ('/compare/ai-native-engineering-vs-ai-coding-tools', 'monthly', '0.7'), ('/compare/upcore-vs-building-in-house', 'monthly', '0.7'),
]
LIBRARY = {'insights': ('monthly', '0.6'), 'learn': ('monthly', '0.7'), 'compare': ('monthly', '0.7')}


def html_file(path):
    if path == '/':
        return 'index.html'
    if path == '/insights':
        return 'insights/index.html'
    return path.strip('/') + '.html'


def fingerprint(html):
    m = re.search(r'<main[^>]*>(.*)</main>', html, re.S)
    body = re.sub(r'\?v=\d+', '', m.group(1) if m else html)
    return hashlib.sha1(re.sub(r'\s+', ' ', body).encode('utf-8')).hexdigest()


def library():
    out = []
    for f in sorted(glob.glob(os.path.join(HERE, 'content', '*.json'))):
        d = json.load(open(f, encoding='utf-8'))
        if 'noindex' in (d.get('robots') or '') or d.get('kind') == 'legal':
            continue
        cf, pr = LIBRARY[d['path'].strip('/').split('/')[0]]
        out.append((d['path'], cf, pr, max(d.get('updated') or '', d.get('published') or '') or '2026-10-07'))
    return out


def seed():
    old = open(OUT, encoding='utf-8').read()
    dates = {loc.replace(C.SITE, '') or '/': lm for loc, lm in re.findall(r'<loc>([^<]+)</loc>.*?<lastmod>([^<]+)</lastmod>', old, re.S)}
    state = {}
    for path, _, _ in PAGES:
        committed = subprocess.run(['git', 'show', 'HEAD:' + html_file(path)], cwd=C.ROOT, capture_output=True, text=True, encoding='utf-8').stdout
        state[path] = {'hash': fingerprint(committed), 'lastmod': dates[path]}
    return state


def main():
    state = seed() if '--seed' in sys.argv else (json.load(open(STATE, encoding='utf-8')) if os.path.exists(STATE) else {})
    today = datetime.date.today().isoformat()
    entries, changed = [], []
    for path, cf, pr in PAGES:
        h = fingerprint(open(os.path.join(C.ROOT, html_file(path)), encoding='utf-8').read())
        prev = state.get(path)
        if not prev or prev['hash'] != h:
            state[path] = {'hash': h, 'lastmod': today}
            changed.append(path)
        entries.append((path, cf, pr, state[path]['lastmod']))
    lib = library()
    paths = [p for p, *_ in entries] + [p for p, *_ in lib]
    dupes = {p for p in paths if paths.count(p) > 1}
    if dupes:
        sys.exit(f'sitemap: listed twice (PAGES and content JSON): {sorted(dupes)}')
    urls = ''.join(f'  <url>\n    <loc>{C.SITE}{p}</loc>\n    <lastmod>{lm}</lastmod>\n    <changefreq>{cf}</changefreq>\n    <priority>{pr}</priority>\n  </url>\n'
                   for p, cf, pr, lm in entries + lib)
    open(OUT, 'w', encoding='utf-8', newline='\n').write(
        '<?xml version="1.0" encoding="UTF-8"?>\n<!-- Generated by tools/v4-build/build_sitemap.py; do not edit by hand. -->\n'
        f'<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n{urls}</urlset>\n')
    json.dump(dict(sorted(state.items())), open(STATE, 'w', encoding='utf-8', newline='\n'), indent=1)
    print(f'sitemap.xml {len(entries) + len(lib)} urls; lastmod moved to {today}: {", ".join(changed) or "none"}')


main()
